<script setup lang="ts">
import {computed,ref} from 'vue'
const props=defineProps<{modelValue:string[],nodes:Record<string,any>[],references:string[],label:(s:string)=>string}>()
const emit=defineEmits<{ 'update:modelValue':[string[]] }>()
const search=ref('')
const all=computed(()=>props.modelValue.includes('ALL'))
const nodes=computed(()=>props.nodes.filter(n=>!n.delete_requested_at&&!['frps','frpc'].includes(n.kind)&&(!search.value||`${n.name} ${n.kind} ${n.address}`.toLowerCase().includes(search.value.toLowerCase()))))
const advanced=computed(()=>props.references.filter(r=>r!=='ALL'&&!r.startsWith('node:')))
function mode(dynamic:boolean){emit('update:modelValue',dynamic?[...props.modelValue.filter(r=>!r.startsWith('node:')&&r!=='ALL'),'ALL']:props.modelValue.filter(r=>r!=='ALL'))}
function toggle(ref:string,checked:boolean){emit('update:modelValue',checked?Array.from(new Set([...props.modelValue,ref])):props.modelValue.filter(r=>r!==ref))}
</script>
<template><fieldset class="member-picker"><legend>节点成员</legend><div class="member-modes"><label><input type="radio" :checked="all" @change="mode(true)">全部节点（默认，自动更新）</label><label><input type="radio" :checked="!all" @change="mode(false)">手动勾选节点</label></div><p class="muted">只会发布订阅用户获授权、已部署运行且兼容所选客户端的节点。停用或部署失败的节点不会加入。</p><template v-if="!all"><input v-model="search" aria-label="搜索策略组节点" placeholder="搜索名称、协议或地址"><div class="node-checks"><label v-for="n in nodes" :key="n.id"><input type="checkbox" :checked="modelValue.includes('node:'+n.id)" @change="toggle('node:'+n.id,($event.target as HTMLInputElement).checked)"><span>{{n.name}} · {{n.kind}}<small>{{n.address}} · {{n.enabled===false?'已停用':n.state==='running'?'运行中':'未就绪'}} · {{n.id.slice(0,8)}}</small></span></label><p v-if="!nodes.length" class="muted">没有匹配节点</p></div></template><details><summary>其他策略组、直连与动态引用</summary><div class="node-checks"><label v-for="r in advanced" :key="r"><input type="checkbox" :checked="modelValue.includes(r)" @change="toggle(r,($event.target as HTMLInputElement).checked)">{{label(r)}}</label></div></details></fieldset></template>
<style scoped>.member-picker{min-width:0;border:1px solid var(--border);border-radius:10px;padding:14px;margin:16px 0}.member-picker legend{font-size:12px;color:var(--accent)}.member-modes{display:flex;flex-wrap:wrap;gap:12px}.member-picker label{display:flex;align-items:flex-start;gap:8px;font-size:12px;line-height:1.6}.member-picker input[type=radio],.member-picker input[type=checkbox]{flex:none;margin-top:3px}.member-picker>input{width:100%;padding:10px;background:var(--input);border:1px solid var(--border);color:var(--ink);border-radius:8px}.node-checks{max-height:240px;overflow:auto;display:grid;gap:10px;padding:12px 0}.node-checks small{display:block;color:var(--muted)}.member-picker p{font-size:12px;line-height:1.7}.member-picker summary{font-size:12px;margin-top:10px}</style>
